    assert_eq!(empty.lines().count(), 1);
    assert!(empty.starts_with("id,day,project,minutes,note"));
}

#[test]
fn csv_quotes() {
    let mut l = Ledger::new();
    l.log(1, "a\"b", 5, "x\ny").unwrap();
    l.log(2, "plain", 6, "").unwrap();
