    }

    pub fn lock_through(&mut self, day: u32) -> Result<(), LedgerError> {
        if !(1..=366).contains(&day) {
            return Err(LedgerError::BadDay(day));
        }
        if day > self.locked {
            self.locked = day;
        }
        Ok(())
    }

    pub fn locked_through(&self) -> u32 {
        self.locked
    }

    pub fn set_rounding(&mut self, r: Rounding) -> Result<(), LedgerError> {
