use crate::ledger::Ledger;

/// One line per entry ordered by (day, id).
pub fn text(ledger: &Ledger) -> String {
    let mut rows: Vec<_> = ledger.entries().iter().collect();
    rows.sort_by_key(|e| (e.day, e.id));
    let mut out = String::new();
