        let line = format!("{:>3} {:<10} {}:{:02} {}", e.day, e.project, e.minutes / 60, e.minutes % 60, e.note);
        out.push_str(line.trim_end());
        out.push('\n');
    }
    out
}

fn field(s: &str) -> String {
    if s.contains(',') || s.contains('"') || s.contains('\n') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}

/// The entries as CSV.
