#[test]
fn undo_and_redo_log() {
    let mut l = Ledger::new();
    assert!(!l.can_undo() && !l.can_redo());
    assert_eq!(l.undo(), Err(LedgerError::NothingToUndo));
    l.log(1, "a", 10, "").unwrap();
