            locked: 0,
        }
    }

    pub fn log(&mut self, day: u32, project: &str, minutes: u32, note: &str) -> Result<u32, LedgerError> {
        if minutes == 0 {
            return Err(LedgerError::ZeroMinutes);
        }
        if !(1..=366).contains(&day) {
            return Err(LedgerError::BadDay(day));
        }
        if day <= self.locked {
