    let mut l = Ledger::new();
    l.log(1, "p", 20, "").unwrap();
    l.log(1, "p", 20, "").unwrap();
    l.set_rounding(Rounding::Down(30)).unwrap();
    assert_eq!(l.billable_total(), 0);
    l.set_rounding(Rounding::Up(30)).unwrap();
    assert_eq!(l.billable_total(), 60);
