#[test]
fn undo_and_redo_respect_locks() {
    let mut l = Ledger::new();
    l.log(1, "a", 10, "").unwrap();
    l.log(5, "b", 10, "").unwrap();
    l.lock_through(5).unwrap();
    assert_eq!(l.undo(), Err(LedgerError::Locked(5)));
    assert_eq!(l.entries().len(), 2);
    assert!(l.can_undo());
    let mut m = Ledger::new();
    m.log(2, "a", 10, "").unwrap();
    m.log(9, "b", 10, "").unwrap();
    m.lock_through(3).unwrap();
    m.undo().unwrap();
